SELECT attempt,database,intent_kind,writer,origin_kind,import_digest,origin_epoch,origin_sequence,expect_fence,expect_acked_epoch,expect_acked_sequence,outcome_kind,answer_kind,failure_reason,lease_database,lease_holder,lease_state,lease_epoch,lease_remaining_ms,CAST(lease_expires_at AS TEXT) AS lease_expires_at,CAST(replayed AS TEXT) AS replayed,refusal_kind,gate_code,gate_detail,existing_digest,offered_digest,current_epoch,CAST(retired_at AS TEXT) AS retired_at,mismatch_fence,mismatch_acked_epoch,mismatch_acked_sequence FROM _fleet_sync_lifecycle_attempts WHERE database=?1 AND outcome_kind IS NULL
